// AMD Build — Auto-generated minified stub
// Run `grunt amd` from the Moodle root to properly build this file.
// This stub allows the theme to load without a Grunt build step.
// For production, always build with Grunt for optimal performance.

define('theme_ltsacademy/chatbot', ['jquery', 'core/log'], function($, log) {
    'use strict';

    var isOpen = false;
    var isLoading = false;
    var badgeDismissed = false;
    var messages = [];
    var apiKey = '';
    var avatarUrl = '';

    var SYSTEM_PROMPT = 'Tu es l\'assistant virtuel de LTS Academy, un organisme de formation professionnelle basé à Berrechid, Maroc. Tu aides les apprenants et entreprises à trouver des informations sur les formations disponibles, les modalités d\'inscription, les tarifs et les programmes (QHSE, comptabilité, langues, informatique, management, etc.). Réponds toujours en français de manière professionnelle, chaleureuse et concise. Si tu ne sais pas quelque chose, dirige l\'utilisateur vers contact@ltsacademy.ma ou le numéro 0660-356877.';

    var $toggle, $window, $messages, $input, $send, $inputWrap, $badge, $quickQuestions;

    function init() {
        var root = document.getElementById('lts-chatbot-root');
        if (!root) { return; }

        apiKey    = root.getAttribute('data-apikey') || '';
        avatarUrl = root.getAttribute('data-avatarurl') || '';

        $toggle        = $('#lts-chat-toggle');
        $window        = $('#lts-chat-window');
        $messages      = $('#lts-chat-messages');
        $input         = $('#lts-chat-input');
        $send          = $('#lts-chat-send');
        $inputWrap     = $('#lts-chat-input-wrap');
        $badge         = $('#lts-chat-badge');
        $quickQuestions = $('#lts-quick-questions');

        $toggle.on('click', toggleChat);
        $('#lts-chat-minimize').on('click', toggleChat);
        $send.on('click', handleSend);
        $input.on('input', onInputChange);
        $input.on('focus', function() { $inputWrap.addClass('lts-focused'); });
        $input.on('blur',  function() { $inputWrap.removeClass('lts-focused'); });
        $input.on('keydown', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                if (!isLoading && $input.val().trim()) { handleSend(); }
            }
        });

        $('.lts-quick-btn').on('click', function() {
            sendMessage($(this).attr('data-question'));
        });

        setTimeout(function() {
            if (!isOpen && !badgeDismissed) { $badge.show(); }
        }, 3000);

        $input.on('input', function() {
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 90) + 'px';
        });
    }

    function toggleChat() {
        isOpen = !isOpen;
        if (isOpen) {
            $window.addClass('lts-chat-open');
            $toggle.attr('aria-expanded', 'true');
            $badge.hide();
            badgeDismissed = true;
            if (messages.length === 0) {
                appendMessage('assistant', '👋 Bonjour ! Je suis l\'assistant de **LTS Academy**.\n\nComment puis-je vous aider aujourd\'hui ? Vous pouvez me poser des questions sur nos formations, les modalités d\'inscription ou tout autre sujet.');
            }
            setTimeout(function() { $input.focus(); }, 300);
        } else {
            $window.removeClass('lts-chat-open');
            $toggle.attr('aria-expanded', 'false');
        }
    }

    function onInputChange() {
        var hasText = $input.val().trim().length > 0;
        if (hasText && !isLoading) {
            $send.addClass('lts-send-active').prop('disabled', false);
        } else {
            $send.removeClass('lts-send-active').prop('disabled', true);
        }
    }

    function handleSend() {
        var text = $input.val().trim();
        if (!text || isLoading) { return; }
        $input.val('').trigger('input').css('height', 'auto');
        sendMessage(text);
    }

    function sendMessage(text) {
        if (!text) { return; }
        $quickQuestions.hide();
        appendMessage('user', text);
        messages.push({ role: 'user', parts: [{ text: text }] });
        setLoading(true);
        if (!apiKey) {
            appendMessage('assistant', '⚠️ La clé API Gemini n\'est pas configurée. Veuillez contacter l\'administrateur ou nous joindre directement au **0660-356877**.');
            setLoading(false);
            return;
        }
        callGeminiAPI(text);
    }

    function callGeminiAPI() {
        var url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + apiKey;
        var contents = messages.map(function(msg) { return { role: msg.role, parts: msg.parts }; });
        var payload = {
            system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
            contents: contents,
            generationConfig: { temperature: 0.7, maxOutputTokens: 1024, topP: 0.9 }
        };
        $.ajax({
            url: url, type: 'POST', contentType: 'application/json',
            data: JSON.stringify(payload), timeout: 30000,
            success: function(response) {
                setLoading(false);
                try {
                    var text = response.candidates[0].content.parts[0].text;
                    messages.push({ role: 'model', parts: [{ text: text }] });
                    appendMessage('assistant', text);
                } catch(e) {
                    appendMessage('assistant', 'Désolé, je n\'ai pas pu traiter votre demande. Veuillez réessayer ou nous contacter directement.');
                }
            },
            error: function(xhr, status) {
                setLoading(false);
                var msg = 'Je rencontre une difficulté technique. ';
                if (status === 'timeout') { msg += 'La connexion a expiré. '; }
                else if (xhr.status === 429) { msg += 'Trop de requêtes. Veuillez patienter quelques secondes. '; }
                else if (xhr.status === 403) { msg += 'Clé API invalide ou quota dépassé. '; }
                msg += '\n\nContactez-nous au **0660-356877** ou **contact@ltsacademy.ma**';
                appendMessage('assistant', msg);
            }
        });
    }

    function appendMessage(role, text) {
        var isUser = (role === 'user');
        var $row = $('<div></div>').addClass('lts-msg-row').addClass(isUser ? 'lts-msg-user' : 'lts-msg-assistant');
        if (!isUser) {
            var $av = $('<div></div>').addClass('lts-msg-avatar');
            if (avatarUrl) {
                $av.append('<img src="' + avatarUrl + '" alt="AI" width="30" height="30">');
            } else {
                $av.html('<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" stroke-width="1.5"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/></svg>');
            }
            $row.append($av);
        }
        var $bubble = $('<div></div>').addClass('lts-msg-bubble');
        if (!isUser) { $bubble.addClass('lts-ai-rendered').html(renderMarkdown(text)); }
        else { $bubble.text(text); }
        $row.append($bubble);
        $messages.append($row);
        $messages[0].scrollTop = $messages[0].scrollHeight;
    }

    function showTypingIndicator() {
        var $row = $('<div></div>').addClass('lts-msg-row lts-msg-assistant').attr('id', 'lts-typing');
        var $av = $('<div></div>').addClass('lts-msg-avatar');
        if (avatarUrl) { $av.append('<img src="' + avatarUrl + '" alt="AI" width="30" height="30">'); }
        var $bubble = $('<div></div>').addClass('lts-msg-bubble lts-typing-indicator').html('<span></span><span></span><span></span>');
        $row.append($av).append($bubble);
        $messages.append($row);
        $messages[0].scrollTop = $messages[0].scrollHeight;
    }

    function setLoading(state) {
        isLoading = state;
        $input.prop('disabled', state);
        $send.prop('disabled', state).toggleClass('lts-send-active', !state && $input.val().trim().length > 0);
        if (state) { showTypingIndicator(); } else { $('#lts-typing').remove(); }
    }

    function renderMarkdown(text) {
        var e = String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
        e = e.replace(/^### (.+)$/gm,'<strong style="display:block;margin:8px 0 4px;color:#1e3a8a;">$1</strong>');
        e = e.replace(/^## (.+)$/gm,'<strong style="display:block;margin:10px 0 6px;font-size:15px;color:#1e3a8a;border-bottom:1px solid #e2e8f0;padding-bottom:4px;">$1</strong>');
        e = e.replace(/\*\*(.+?)\*\*/g,'<strong style="font-weight:700;color:#1e3a8a;">$1</strong>');
        e = e.replace(/\*(.+?)\*/g,'<em>$1</em>');
        e = e.replace(/`([^`]+)`/g,'<code style="background:rgba(30,58,138,0.07);color:#be185d;border-radius:4px;padding:1px 5px;font-family:monospace;font-size:12px;">$1</code>');
        e = e.replace(/^[-*•] (.+)$/gm,'<div style="display:flex;align-items:flex-start;gap:7px;padding:2px 0;"><span style="color:#3b82f6;font-weight:700;flex-shrink:0;">▸</span><span>$1</span></div>');
        e = e.replace(/\n\n+/g,'<br><br>');
        e = e.replace(/\n/g,'<br>');
        return e;
    }

    return { init: init };
});
